3	/**
4	 * Page Object for the Imagify Settings page.
5	 * URL: /wp-admin/options-general.php?page=imagify
6	 */
7	export class SettingsPage {
8		readonly page: Page;
9		readonly apiKeyInput: Locator;
10		readonly saveButton: Locator;
11		readonly successNotice: Locator;
12	
13		constructor( page: Page ) {
14			this.page = page;
15			this.apiKeyInput  = page.locator( '#imagify-api-key, [name="imagify_settings[api_key]"]' ).first();
16			this.saveButton   = page.locator( '#submit' );
17			this.successNotice = page.locator( '.notice-success, .updated' ).first();
18		}
19	
20		async goto(): Promise<void> {
21			await this.page.goto( '/wp-admin/options-general.php?page=imagify' );
22			await this.page.waitForLoadState( 'networkidle' );
23		}
24	
25		async isLoaded(): Promise<boolean> {
26			const title = this.page.locator( 'h1, h2' ).filter( { hasText: /imagify/i } );
27			return await title.count() > 0;
28		}
29	
30		async setApiKey( key: string ): Promise<void> {
31			await this.apiKeyInput.fill( key );
32			await this.saveButton.click();
33			await this.successNotice.waitFor( { timeout: 10_000 } );
34		}
35	
36		async getApiKey(): Promise<string> {
37			return ( await this.apiKeyInput.inputValue() ) ?? '';
38		}
39	
40		async expectNoFatalError(): Promise<void> {
41			await expect( this.page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
42		}
43	}
