3	/**
4	 * Default wp-env admin credentials. Override via env vars when running
5	 * against a different environment.
6	 */
7	export const ADMIN_USER = process.env.IMAGIFY_ADMIN_USER ?? 'admin';
8	export const ADMIN_PASS = process.env.IMAGIFY_ADMIN_PASS ?? 'password';
9	
10	/**
11	 * Log in as the WordPress administrator. Idempotent: if a session cookie is
12	 * already set, navigation hits /wp-admin/ directly and skips the form.
13	 */
14	export async function loginAsAdmin( page: Page ): Promise<void> {
15		await page.goto( '/wp-login.php', { waitUntil: 'networkidle' } );
16	
17		// Already logged in? Cookie redirects to wp-admin.
18		if ( page.url().includes( '/wp-admin/' ) ) {
19			return;
20		}
21	
22		await page.getByLabel( 'Username or Email Address' ).waitFor( { timeout: 5000 } );
23		await page.getByLabel( 'Username or Email Address' ).fill( ADMIN_USER );
24		await page.getByLabel( 'Password', { exact: true } ).fill( ADMIN_PASS );
25	
26		await page.getByRole( 'button', { name: 'Log In' } ).click();
27		await page.waitForURL( /\/wp-admin\/?/, { timeout: 20000 } );
28	}
