222		/**
223		 * Runs the next-gen generation
224		 *
225		 * @param array $contexts An array of contexts (WP/Custom folders).
226		 * @param array $formats An array of format to generate.
227		 *
228		 * @return array
229		 */
230		public function run_generate_nextgen( array $contexts, array $formats ) {
231			if ( ! $this->can_optimize() ) {
232				return [
233					'success' => false,
234					'message' => 'over-quota',
235				];
236			}
237	
238			delete_transient( 'imagify_stat_without_next_gen' );
239	
240			$medias = [];
241	
242			foreach ( $contexts as $context ) {
243				foreach ( $formats as $format ) {
244					$media = $this->get_bulk_instance( $context )->get_optimized_media_ids_without_format( $format );
245					if ( ! $media['ids'] && $media['errors']['no_file_path'] ) {
246						// Error.
247						return [
248							'success' => false,
249							'message' => __( 'The path to the selected files could not be retrieved.', 'imagify' ),
250						];
251					}
252	
253					if ( $media['ids'] ) {
254						$medias[ $context ] = $media['ids'];
255					}
256				}
257			}
258	
259			if ( empty( $medias ) ) {
260				return [
261					'success' => false,
262					'message' => 'no-images',
263				];
264			}
265	
266			$total = 0;
267	
268			foreach ( $medias as $context => $media_ids ) {
269				$total += count( $media_ids );
270	
271				foreach ( $media_ids as $media_id ) {
272					try {
273						as_enqueue_async_action(
274							'imagify_convert_next_gen',
275							[
276								'id'      => $media_id,
277								'context' => $context,
278							],
279							"imagify-{$context}-convert-nextgen"
280						);
281					} catch ( Exception $exception ) { // phpcs:ignore Generic.CodeAnalysis.EmptyStatement.DetectedCatch
282						// nothing to do.
283					}
284				}
285			}
286	
287			set_transient( 'imagify_missing_next_gen_total', $total, HOUR_IN_SECONDS );
288	
289			return [
290				'success' => true,
291				'message' => $total,
292			];
293		}
