344		/**
345		 * Optimize all files from a media, whatever this media’s previous optimization status (will be restored if needed).
346		 * This is used by the bulk optimization page.
347		 *
348		 * @since 1.9
349		 *
350		 * @param  int    $media_id The media ID.
351		 * @param  string $context  The context.
352		 * @param  int    $level    The optimization level.
353		 *
354		 * @return bool|WP_Error True if successfully launched. A \WP_Error instance on failure.
355		 */
356		private function force_optimize( int $media_id, string $context, int $level ) {
357			if ( ! $this->can_optimize() ) {
358				$this->decrease_counter( $context );
359	
360				return false;
361			}
362	
363			$process = imagify_get_optimization_process( $media_id, $context );
364			$data    = $process->get_data();
365	
366			// Restore before re-optimizing.
367			if ( $data->is_optimized() ) {
368				$result = $process->restore();
369	
370				if ( is_wp_error( $result ) ) {
371					$this->decrease_counter( $context );
372	
373					// Return an error message.
374					return $result;
375				}
376			}
377	
378			return $process->optimize( $level );
379		}
