621		 * @return array The array of unique contexts ('wp' or 'custom-folders').
622		 */
623		public function get_contexts() {
624			$contexts = [];
625			$types    = [];
626	
627			// Library: in each site.
628			if ( ! is_network_admin() ) {
629				$types['library|wp'] = 1;
630			}
631	
632			// Custom folders: in network admin only if network activated, in each site otherwise.
633			if (
634				imagify_can_optimize_custom_folders()
635				&&
636				(
637					( imagify_is_active_for_network() && is_network_admin() )
638					||
639					! imagify_is_active_for_network()
640				)
641			) {
642				$types['custom-folders|custom-folders'] = 1;
643			}
644	
645			/**
646			 * Filter the types to display in the bulk optimization page.
647			 *
648			 * @since  1.7.1
649			 *
650			 * @param array $types The folder types displayed on the page. If a folder type is "library", the context should be suffixed after a pipe character. They are passed as array keys.
651			 */
652			$types = wpm_apply_filters_typed( 'array', 'imagify_bulk_page_types', $types );
653			$types = array_filter( (array) $types );
654	
655			if ( isset( $types['library|wp'] ) ) {
656				$contexts[] = 'wp';
657			}
658	
659			if ( isset( $types['custom-folders|custom-folders'] ) ) {
660				$folders_instance = \Imagify_Folders_DB::get_instance();
661	
662				if ( ! $folders_instance->has_items() ) {
663					if ( ! in_array( 'wp', $contexts, true ) ) {
664						$contexts[] = 'wp';
665					}
666				} elseif ( $folders_instance->has_active_folders() ) {
667					$contexts[] = 'custom-folders';
668				}
669			}
670	
671			return $contexts;
672		}
