11	/**
12	 * Class to use for bulk for custom folders.
13	 *
14	 * @since 1.9
15	 */
16	class CustomFolders extends AbstractBulk {
17		/**
18		 * Context "short name".
19		 *
20		 * @var string
21		 * @since 1.9
22		 */
23		protected $context = 'custom-folders';
24	
25		/**
26		 * Get all unoptimized media ids.
27		 *
28		 * @since 1.9
29		 *
30		 * @param  int $optimization_level The optimization level.
31		 *
32		 * @return array A list of unoptimized media IDs.
33		 */
34		public function get_unoptimized_media_ids( $optimization_level ) {
35			$this->set_no_time_limit();
36	
37			/**
38			 * Get the folders from DB.
39			 */
40			$folders = Imagify_Custom_Folders::get_folders(
41				[
42					'active' => true,
43				]
44			);
45	
46			if ( ! $folders ) {
47				return [];
48			}
49	
50			/**
51			 * Fires before getting file IDs.
52			 *
53			 * @since 1.7
54			 *
55			 * @param array $folders            An array of folders data.
56			 * @param int   $optimization_level The optimization level that will be used for the optimization.
57			 */
58			do_action( 'imagify_bulk_optimize_files_before_get_files', $folders, $optimization_level );
59	
60			/**
61			 * Get the files from DB, and from the folders.
62			 */
63			$files = Imagify_Custom_Folders::get_files_from_folders(
64				$folders,
65				[
66					'optimization_level' => $optimization_level,
67				]
68			);
69	
70			if ( ! $files ) {
71				return [];
72			}
73	
74			foreach ( $files as $k => $file ) {
75				$files[ $k ] = $file['file_id'];
76			}
77	
78			return $files;
79		}
80	
81		/**
82		 * Get ids of all optimized media without Next gen versions.
83		 *
84		 * @since 2.2
85		 *
86		 * @param string $format Format we are looking for. (webp|avif).
87		 *
88		 * @return array {
89		 *     @type array $ids    A list of media IDs.
90		 *     @type array $errors {
91		 *         @type array $no_file_path A list of media IDs.
92		 *         @type array $no_backup    A list of media IDs.
93		 *     }
94		 * }
95		 */
96		public function get_optimized_media_ids_without_format( $format ) {
97			global $wpdb;
98	
99			$this->set_no_time_limit();
100	
101			$files_table   = Imagify_Files_DB::get_instance()->get_table_name();
102			$folders_table = Imagify_Folders_DB::get_instance()->get_table_name();
103			$mime_types    = Imagify_DB::get_mime_types( 'image' );
104			// Remove single quotes and explode string into array.
105			$mime_types_array = explode( ',', str_replace( "'", '', $mime_types ) );
106	
107			// Iterate over array and check if string contains input.
108			foreach ( $mime_types_array as $item ) {
109				if ( strpos( $item, $format ) !== false ) {
110					$mime = $item;
111					break;
112				}
113			}
114			if ( ! isset( $mime ) && empty( $mime ) ) {
115				$mime = 'image/webp';
116			}
117			$mime = trim( $mime );
118			$mime_types     = str_replace( [ ", '" . $mime . "'", ",'" . $mime . "'" ], '', $mime_types );
119			$nextgen_suffix = constant( imagify_get_optimization_process_class_name( 'custom-folders' ) . '::' . strtoupper( $format ) . '_SUFFIX' );
120			$files          = $wpdb->get_results(
121				$wpdb->prepare( // WPCS: unprepared SQL ok.
122					"
123				SELECT fi.file_id, fi.path
124				FROM $files_table as fi
125				INNER JOIN $folders_table AS fo
126					ON ( fi.folder_id = fo.folder_id AND fo.active = 1 )
127				WHERE
128					fi.mime_type IN ( $mime_types )
129					AND ( fi.status = 'success' OR fi.status = 'already_optimized' )
130					AND fi.data NOT LIKE %s
131				ORDER BY fi.file_id DESC",
132					'%' . $wpdb->esc_like( $nextgen_suffix . '";a:4:{s:7:"success";b:1;' ) . '%'
133				)
134			);
135	
136			$wpdb->flush();
137			unset( $mime_types, $files_table, $folders_table, $nextgen_suffix, $mime );
138	
139			$data = [
140				'ids'    => [],
141				'errors' => [
142					'no_file_path' => [],
143					'no_backup'    => [],
144				],
145			];
146	
147			if ( ! $files ) {
148				return $data;
149			}
150	
151			foreach ( $files as $file ) {
152				$file_id = absint( $file->file_id );
153	
154				if ( empty( $file->path ) ) {
155					// Problem.
156					$data['errors']['no_file_path'][] = $file_id;
157					continue;
158				}
159	
160				$file_path   = Imagify_Files_Scan::remove_placeholder( $file->path );
161				$backup_path = Imagify_Custom_Folders::get_file_backup_path( $file_path );
162	
163				// Skip files whose extension already matches the target format
164				// (e.g. a .webp file stored with incorrect post_mime_type).
165				if ( strtolower( pathinfo( $file_path, PATHINFO_EXTENSION ) ) === $format ) {
166					continue;
167				}
168	
169				if ( ! $this->filesystem->exists( $backup_path ) ) {
170					// No backup, no WebP.
171					$data['errors']['no_backup'][] = $file_id;
172					continue;
173				}
174	
175				$data['ids'][] = $file_id;
176			}
177	
178			return $data;
179		}
