181		/**
182		 * Get the context data.
183		 *
184		 * @since 1.9
185		 *
186		 * @return array {
187		 *     The formated data.
188		 *
189		 *     @type string $count-optimized Number of media optimized.
190		 *     @type string $count-errors    Number of media having an optimization error, with a link to the page listing the optimization errors.
191		 *     @type string $optimized-size  Optimized filesize.
192		 *     @type string $original-size   Original filesize.
193		 * }
194		 */
195		public function get_context_data() {
196			$data = [
197				'count-optimized' => Imagify_Files_Stats::count_optimized_files(),
198				'count-errors'    => Imagify_Files_Stats::count_error_files(),
199				'optimized-size'  => Imagify_Files_Stats::get_optimized_size(),
200				'original-size'   => Imagify_Files_Stats::get_original_size(),
201				'errors_url'      => get_imagify_admin_url( 'folder-errors', $this->context ),
