69		 * Gets the credential's value from either an environment variable (stored locally on the machine or CI) or from a
70		 * local constant defined in `tests/env/local/imagify-api.php`.
71		 *
72		 * @param string $name Name of the environment variable or constant to find. Example: 'IMAGIFY_TESTS_API_KEY'.
73		 *
74		 * @return string       Return the value if available. An empty string otherwise.
75		 */
76		protected function getApiCredential( $name ) {
77			$var = getenv( $name );
