122		 * Set the value of a private/protected property.
123		 *
124		 * @param string        $property Property name for which to gain access.
125		 * @param string|object $class    Class name for a static property, or instance for an instance property.
126		 * @param mixed         $value    The value to set to the property.
127		 *
128		 * @return mixed                   The previous value of the property.
129		 * @throws ReflectionException Throws an exception if property does not exist.
130		 *
131		 */
132		protected function setPropertyValue( $property, $class, $value ) {
133			$ref = $this->get_reflective_property( $property, $class );
134	
135			if ( is_object( $class ) ) {
136				$previous = $ref->getValue( $class );
137				// Instance property.
