6	/**
7	 * Service class that resets Imagify's internal optimization state.
8	 *
9	 * Clears transients and cancels stuck ActionScheduler jobs without
10	 * touching user settings or media optimization data.
11	 *
12	 * @since 2.3
13	 */
14	class ResetInternalState {
15	
16		/**
17		 * Run the full internal-state reset.
18		 *
19		 * @since 2.3
20		 *
21		 * @return void
22		 */
23		public function reset(): void {
24			$this->cancel_actionscheduler_jobs();
25			$this->delete_named_transients();
26			$this->delete_pattern_transients();
27	
28			/**
29			 * Fires after Imagify's internal state has been reset.
30			 *
31			 * @since 2.3
32			 */
33			do_action( 'imagify_after_reset_internal_state' );
34		}
35	
36		/**
37		 * Cancel all pending ActionScheduler bulk-optimization jobs.
38		 *
39		 * @since 2.3
40		 *
41		 * @return void
42		 */
43		private function cancel_actionscheduler_jobs(): void {
44			if ( ! function_exists( 'as_cancel_all_pending_actions' ) ) {
45				return;
46			}
47	
48			as_cancel_all_pending_actions( 'imagify_optimize_media' );
49			as_cancel_all_pending_actions( 'imagify_convert_next_gen' );
50		}
51	
52		/**
53		 * Delete well-known Imagify transients related to optimization state.
54		 *
55		 * User settings (imagify_settings) are intentionally excluded.
56		 *
57		 * @since 2.3
58		 *
59		 * @return void
60		 */
61		private function delete_named_transients(): void {
62			// Bulk running state.
63			delete_transient( 'imagify_custom-folders_optimize_running' );
64			delete_transient( 'imagify_wp_optimize_running' );
65			delete_transient( 'imagify_bulk_optimization_complete' );
66			delete_transient( 'imagify_missing_next_gen_total' );
67			delete_transient( 'imagify_bulk_optimization_result' );
68			delete_transient( 'imagify_bulk_optimization_level' );
69			delete_transient( 'imagify_stat_without_next_gen' );
70			delete_transient( 'imagify_large_library' );
71			delete_transient( 'imagify_max_image_size' );
72			delete_transient( 'imagify_user_cache' );
73			delete_transient( 'imagify_attachments_number_modal' );
74			delete_transient( 'imagify_user' );
75	
76			// API / license cache.
77			delete_site_transient( 'imagify_check_api_version' );
78			delete_site_transient( 'imagify_check_licence_1' );
79			delete_site_transient( 'imagify_user' );
80		}
81	
82		/**
83		 * Delete pattern-based transients (process locks, auto-optimize flags, RPC
84		 * tokens and legacy WP-Background-Process batch rows) using direct DB queries.
85		 *
86		 * @since 2.3
87		 *
88		 * @return void
89		 */
90		private function delete_pattern_transients(): void {
91			global $wpdb;
92	
93			$patterns = [
94				'_transient_imagify\_%\_process\_locked',
95				'_site_transient_imagify\_%\_process\_lock%',
96				'_transient_%imagify-auto-optimize-%',
97				'_transient_%imagify\_rpc\_%',
98				'_transient_imagify\_optimize\_media\_batch%',
99				'_transient_imagify\_convert\_next\_gen\_batch%',
100			];
101	
102			foreach ( $patterns as $pattern ) {
103				$wpdb->query( // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
104					$wpdb->prepare(
105						"DELETE FROM {$wpdb->options} WHERE option_name LIKE %s", // phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared
106						$pattern
107					)
108				);
109			}
110		}
111	}
